package com.hozefa.threepattipro.nativeapp;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;

public class ScoreTrendModelTest {
    private Map<String,Object> m(Object...p){return SessionLeaderboard.FirebaseMap.of(p);}
    private List<Map<String,Object>> list(Map<String,Object>...p){return Arrays.asList(p);}
    private List<Map<String,Object>> roster(){List<Map<String,Object>> r=new ArrayList<>();for(int i=0;i<6;i++)r.add(m("id","p"+i,"name","Player "+i));return r;}
    private Map<String,Object> r(String id,int n,Object...scores){return m("id",id,"type","hukum","timestamp","2026-10-29T10:00:"+String.format(Locale.ROOT,"%02d",n)+"Z","playerIds",Arrays.asList("p0","p1","p2","p3","p4","p5"),"scoreChanges",m(scores));}
    @Test public void allPlayersShareOneOrderedTimelineWithNegativeAndSkippedRounds(){List<Map<String,Object>> source=list(r("later",2,"p0",-155,"p1",310),r("first",1,"p0",310,"p2",155));ScoreboardModel board=new ScoreboardModel(roster(),source,Collections.emptyList());ScoreTrendModel model=new ScoreTrendModel(source,board,roster(),null);assertEquals(6,model.series.size());assertEquals(3,model.frames.size());assertEquals("first",model.frames.get(1).key);assertEquals(310,model.frames.get(1).values[0]);assertEquals(155,model.frames.get(2).values[0]);assertEquals(155,model.frames.get(2).values[2]);for(int i=0;i<6;i++)assertEquals(board.byId.get(model.series.get(i).id).points,model.frames.get(2).values[i]);assertFalse(model.pending);}
    @Test public void sessionScopeNeverMixesOtherSessionsAndIncludesBotNames(){Map<String,Object> session=m("id","cf2_one","source","online","endTime","2026-10-29T12:00:00Z"),one=r("one",1,"p0",310,"bot_a",155),other=r("other",2,"p0",999);one.putAll(m("source","online","sessionId","cf2_one","participantIds",Arrays.asList("p0","bot_a"),"participants",list(m("playerId","bot_a","name","Computer 2","kind","bot"))));other.put("sessionId","elsewhere");List<Map<String,Object>> scope=SessionLeaderboard.rounds(list(one,other),list(session),"cf2_one");ScoreboardModel board=SessionLeaderboard.model(roster(),list(one,other),list(session),session,null);ScoreTrendModel model=new ScoreTrendModel(scope,board,roster(),null);assertEquals(1,model.totalRounds);assertEquals(155,model.frames.get(1).values[model.series.indexOf(model.series.stream().filter(s->s.id.equals("bot_a")).findFirst().get())]);assertEquals("Computer 2",model.series.stream().filter(s->s.id.equals("bot_a")).findFirst().get().name);}
    @Test public void missingExportsShowOnlyKnownRoundsAndSeparateLiveTotal(){List<Map<String,Object>> source=list(r("one",1,"p0",310));Map<String,Object> remote=m("status","playing","totalRounds",3,"pendingExports",2);ScoreboardModel board=ScoreboardModel.standings(list(m("id","p0","name","Player 0","score",500,"roundsPlayed",3)));ScoreTrendModel model=new ScoreTrendModel(source,board,roster(),remote);assertTrue(model.pending);assertEquals(3,model.frames.size());assertEquals(1,model.frames.get(1).round);assertEquals(3,model.frames.get(2).round);assertEquals(500,model.frames.get(2).values[0]);assertTrue(model.frames.get(2).separate);}
    @Test public void inconsistentHistoryNeverInventsAnIntermediateCurve(){List<Map<String,Object>> source=list(r("one",1,"p0",310));ScoreboardModel board=ScoreboardModel.standings(list(m("id","p0","name","Player 0","score",500,"roundsPlayed",1)));ScoreTrendModel model=new ScoreTrendModel(source,board,roster(),m("status","playing","totalRounds",1));assertTrue(model.pending);assertEquals(2,model.frames.size());assertTrue(model.frames.get(1).separate);assertEquals(500,model.frames.get(1).values[0]);}
    @Test public void exportedHistoryReplacesLiveDotWithoutDoubleCounting(){List<Map<String,Object>> source=list(r("one",1,"p0",310),r("two",2,"p0",190));ScoreboardModel board=ScoreboardModel.standings(list(m("id","p0","name","Player 0","score",500,"roundsPlayed",2)));ScoreTrendModel model=new ScoreTrendModel(source,board,roster(),m("status","playing","totalRounds",2,"pendingExports",0));assertFalse(model.pending);assertEquals(3,model.frames.size());assertEquals(500,model.frames.get(2).values[0]);assertFalse(model.frames.get(2).separate);}
    @Test public void historicalDeletionRebuildsAccurateTotalsAndEmptyDataIsSafe(){Map<String,Object> a=r("one",1,"p0",310),b=r("two",2,"p0",-155);List<Map<String,Object>> after=list(b);ScoreTrendModel model=new ScoreTrendModel(after,new ScoreboardModel(roster(),after,Collections.emptyList()),roster(),null);assertEquals(-155,model.frames.get(1).values[0]);ScoreTrendModel empty=new ScoreTrendModel(Collections.emptyList(),new ScoreboardModel(roster(),Collections.emptyList(),Collections.emptyList()),roster(),null);assertTrue(empty.series.isEmpty());assertEquals(1,empty.frames.size());}
    @Test public void largePointValuesStayExact(){List<Map<String,Object>> source=list(r("one",1,"p0",4000000000L),r("two",2,"p0",-2));ScoreTrendModel model=new ScoreTrendModel(source,new ScoreboardModel(roster(),source,Collections.emptyList()),roster(),null);assertEquals(3999999998L,model.frames.get(2).values[0]);}
}
